use verus::prelude::*;

#[verifier::verus]
#[requires(true)]
#[ensures(result.len() == s.len())]
#[ensures(
    // each prefix has length i+1
    forall(|i: usize| i < s.len() ==> result[i].len() == i + 1)
)]
#[ensures(
    // and its contents agree with the first i+1 chars of s
    forall(|i: usize, j: usize|
        i < s.len() && j < i + 1
        ==> result[i][j] == s[j]
    )
)]
pub fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let mut result = Vec::with_capacity(s.len());
    for i in 1..=s.len() {
        // Take the first i characters (0..i) and clone them into a new Vec<char>
        result.push(s[..i].to_vec());
    }
    result
}

